#include "MetalEqWebUiResources.h"

#if METALEQ_UI_EMBEDDED
 // Generated by juceaide from the packaged UI zip (see CMakeLists.txt). The
 // include path for this header is added to both the plugin and its tests.
 #include <BinaryData.h>
#endif

#include <cstring>
#include <unordered_map>

namespace metaleq::ui
{

namespace
{
    /** Serves the placeholder page when the real UI bundle is missing. */
    juce::WebBrowserComponent::Resource fallbackResource()
    {
        static constexpr const char* html =
            "<!doctype html>\n"
            "<html><head><meta charset=\"utf-8\"><title>MetalEQ</title></head>\n"
            "<body style=\"background:#111419;color:#c3c8d0;font-family:sans-serif;"
            "display:flex;align-items:center;justify-content:center;height:100vh;margin:0\">"
            "<div style=\"text-align:center;max-width:34em;padding:0 16px\">"
            "<h1 style=\"color:#fff\">MetalEQ</h1>"
            "<p>The compiled web interface was not embedded in this build "
            "(npm run build in Gui/ was unavailable at configure time).</p>"
            "<p>The plugin is switching to the built-in native interface.</p>"
            "</div></body></html>";

        const auto len = std::strlen (html);
        std::vector<std::byte> data (len);
        std::memcpy (data.data(), html, len);

        return { std::move (data), juce::String { "text/html" } };
    }

    /** The archive, created once from the embedded binary data. */
    juce::ZipFile* getArchive()
    {
       #if METALEQ_UI_EMBEDDED
        static auto archive = []
        {
            auto stream = std::make_unique<juce::MemoryInputStream> (
                BinaryData::metaleq_ui_zip, (size_t) BinaryData::metaleq_ui_zipSize, false);
            return std::make_unique<juce::ZipFile> (std::move (stream));
        }();
        return archive.get();
       #else
        return nullptr;
       #endif
    }

    /** Validates and normalises a resource URL into an archive path.

        Accepts "/" (-> "index.html") and "/some/relative/path". Rejects
        anything with a scheme, "..", backslashes, NUL bytes or control
        characters, so the archive can only ever be asked for its own files.
    */
    std::optional<juce::String> normalisePath (const juce::String& url)
    {
        if (url.isEmpty())
            return std::nullopt;

        // Query strings and fragments are not used by the single-page app;
        // strip them so "?v=1" cannot become part of the lookup key.
        auto path = url.upToFirstOccurrenceOf ("?", false, false)
                         .upToFirstOccurrenceOf ("#", false, false);

        if (path.startsWithIgnoreCase ("http://") || path.startsWithIgnoreCase ("https://")
            || path.startsWithIgnoreCase ("file:") || path.startsWithIgnoreCase ("data:"))
            return std::nullopt;

        while (path.startsWithChar ('/'))
            path = path.substring (1);

        if (path.isEmpty())
            path = "index.html";

        if (path.containsChar ('\\') || path.containsChar ('\0')
            || path.contains ("..") || path.containsChar ('\n') || path.containsChar ('\r'))
            return std::nullopt;

        for (const auto c : path)
            if (c < 0x20)
                return std::nullopt;

        return path;
    }
}

bool isWebUiEmbedded() noexcept
{
   #if METALEQ_UI_EMBEDDED
    return getArchive() != nullptr;
   #else
    return false;
   #endif
}

const char* webUiMimeTypeFor (const juce::String& extension) noexcept
{
    static const std::unordered_map<juce::String, const char*> mimeMap {
        { "htm",   "text/html" },
        { "html",  "text/html" },
        { "txt",   "text/plain" },
        { "css",   "text/css" },
        { "js",    "text/javascript" },
        { "mjs",   "text/javascript" },
        { "json",  "application/json" },
        { "svg",   "image/svg+xml" },
        { "png",   "image/png" },
        { "jpg",   "image/jpeg" },
        { "jpeg",  "image/jpeg" },
        { "webp",  "image/webp" },
        { "ico",   "image/vnd.microsoft.icon" },
        { "woff",  "font/woff" },
        { "woff2", "font/woff2" },
        { "map",   "application/json" },
    };

    if (const auto it = mimeMap.find (extension.toLowerCase()); it != mimeMap.end())
        return it->second;

    return "application/octet-stream";
}

std::optional<juce::WebBrowserComponent::Resource> findWebUiResource (const juce::String& url)
{
    const auto path = normalisePath (url);
    if (! path.has_value())
        return std::nullopt;

    if (auto* archive = getArchive())
    {
        // The Vite build emits forward slashes; ZipFile entries use the same
        // convention, so a straight lookup is enough after validation.
        if (const auto* entry = archive->getEntry (*path))
        {
            // createStreamForEntry transfers ownership to the caller.
            std::unique_ptr<juce::InputStream> stream (archive->createStreamForEntry (*entry));
            if (stream == nullptr)
                return std::nullopt;

            const auto size = (size_t) stream->getTotalLength();
            std::vector<std::byte> data (size);
            if (size > 0 && stream->read (data.data(), size) != (int) size)
                return std::nullopt;

            return juce::WebBrowserComponent::Resource {
                std::move (data),
                juce::String (webUiMimeTypeFor (entry->filename.fromLastOccurrenceOf (".", false, false)))
            };
        }
    }

    // The real page (and nothing else) gets the inline placeholder, so a
    // missing bundle degrades to a readable message instead of a blank view.
    if (*path == "index.html")
        return fallbackResource();

    return std::nullopt;
}

} // namespace metaleq::ui
